  for (const sy of [side, -side]) {
    const y = me.y + sy;
    if (y < 0 || y >= state.map.height) continue;
    if (blocked.has(me.x + ',' + y)) continue;
    return { type: 'move', x: me.x, y };
  }
  return { type: 'idle' };
